 public partial class VaultGame {
  public int DungeonIndex{get;private set;} public int HighestUnlocked{get;private set;} public int Credits{get;private set;} public DungeonProfile CurrentDungeon=>DungeonCatalog.Get(DungeonIndex);
  public int SelectedStageId{get;private set;}=-1; public int ExpeditionTokens{get;private set;} public IReadOnlyList<int> ClearedExpeditionStages=>clearedExpeditionStages;
  readonly List<int> clearedExpeditionStages=new List<int>();
  public ExpeditionStage SelectedExpeditionStage=>SelectedStageId<0?null:ExpeditionMap.Get(SelectedStageId);
  public const int ArtifactCapacity=24; public readonly List<ArtifactItem> ArtifactInventory=new List<ArtifactItem>();public ArtifactItem[] EquippedArtifacts=new ArtifactItem[2];public float ArtifactShield{get;private set;}
  readonly Dictionary<string,float> artifactTimers=new Dictionary<string,float>(); float ArtifactTimer(ArtifactItem a)=>a!=null&&artifactTimers.TryGetValue(a.id,out float value)?value:0;float armorKillTimer,armorDashTimer;float reloadSurge;float artifactCombatClock;readonly Dictionary<string,float> reloadSurgeExpiry=new Dictionary<string,float>();int shopCycle; readonly List<ShopOffer> shopStock=new List<ShopOffer>();Vector2 artifactScroll;bool artifactPage;
  [Serializable] class ProgressSave{public int dungeon,unlocked,credits,cycle,stage=-1,tokens;public bool hasSelectedStage;public List<int> clearedStages;public List<ArtifactItem> artifacts;public string[] equipped;public List<int> purchased;}
  public class ShopOffer{public Gun gun;public ArmorItem armor;public ArtifactItem artifact;public MeleeWeaponItem melee;public int cost;public bool purchased;}
  public IReadOnlyList<ShopOffer> ShopStock=>shopStock;
  public void OpenArtifactInventory(){artifactPage=true;if(!InventoryOpen)ToggleInventory();}
  readonly List<int> shopPurchased=new List<int>();
  public void ProgressionInitialize(){bool existingSave=!smoke&&PlayerPrefs.HasKey("Vault.Progression.v1");if(!smoke&&PlayerPrefs.HasKey("Vault.Progression.v1")){try{var s=JsonUtility.FromJson<ProgressSave>(PlayerPrefs.GetString("Vault.Progression.v1"));DungeonIndex=Mathf.Clamp(s.dungeon,0,2);HighestUnlocked=Mathf.Clamp(s.unlocked,0,2);Credits=Mathf.Max(0,s.credits);shopCycle=s.cycle;SelectedStageId=s.hasSelectedStage?Mathf.Clamp(s.stage,0,ExpeditionMap.StageCount-1):-1;ExpeditionTokens=Mathf.Max(0,s.tokens);if(s.clearedStages!=null)foreach(int id in s.clearedStages)if(id>=0&&id<ExpeditionMap.StageCount&&!clearedExpeditionStages.Contains(id))clearedExpeditionStages.Add(id);if(s.artifacts!=null)foreach(var a in s.artifacts)if(a!=null&&!string.IsNullOrEmpty(a.id)&&ArtifactInventory.Count<ArtifactCapacity)ArtifactInventory.Add(a);if(s.equipped!=null)for(int i=0;i<Math.Min(2,s.equipped.Length);i++)EquippedArtifacts[i]=ArtifactInventory.Find(a=>a.id==s.equipped[i]);if(s.purchased!=null)shopPurchased.AddRange(s.purchased);}catch(Exception e){Debug.LogWarning("Progression load failed: "+e.GetType().Name);}}DebtSkillsInitialize();if(!existingSave){var starter=ArtifactCatalog.CreateCatalog(ModuleProductCatalog.Get(0,0).id,Rarity.Common,1);ArtifactInventory.Add(starter);EquippedArtifacts[0]=starter;SaveProgression();}CreateShopStock();}
  void SaveProgression(){if(smoke)return;PlayerPrefs.SetString("Vault.Progression.v1",JsonUtility.ToJson(new ProgressSave{dungeon=DungeonIndex,unlocked=HighestUnlocked,credits=Credits,cycle=shopCycle,stage=SelectedStageId,hasSelectedStage=SelectedStageId>=0,tokens=ExpeditionTokens,clearedStages=clearedExpeditionStages,artifacts=ArtifactInventory,equipped=new[]{EquippedArtifacts[0]?.id,EquippedArtifacts[1]?.id},purchased=shopPurchased}));PlayerPrefs.Save();}
  public void EnterHub(){runDamage=runFire=runVitality=runDash=runChain=runHarvest=0;ClearRunUpgradeHistory();shopSellingPage=false;pendingSaleKey=null;InventoryOpen=false;Time.timeScale=1;ResetArtifactCombat();RefreshPermanentStats();hp=maxHp;screen=Screen.Hub;BuildHub();}
  public bool EnterDungeon(int index){if(index<0||index>HighestUnlocked||index>=3)return false;SelectedStageId=-1;ResetExpeditionMission();DungeonIndex=index;ClearRunUpgradeHistory();ResetArtifactCombat();SaveProgression();StartRun();return true;}
  public bool EnterExpeditionStage(int stageId){if(stageId<0||stageId>=ExpeditionMap.StageCount)return false;var stage=ExpeditionMap.Get(stageId);if(stage.level>DebtLevel)return false;SelectedStageId=stageId;ResetExpeditionMission();DungeonIndex=stage.legacyDungeonIndex;ClearRunUpgradeHistory();ResetArtifactCombat();SaveProgression();StartRun();return true;}
  public void OnDungeonFinished(bool won){if(won){ExpeditionRunCompleted();if(SelectedExpeditionStage==null||MissionCompleted){HighestUnlocked=Mathf.Min(2,Mathf.Max(HighestUnlocked,DungeonIndex+1));AwardCredits(ScaleScrap(new[]{5000000,10000000,20000000}[DungeonIndex]));if(SelectedStageId>=0)GrantExpeditionReward(SelectedStageId);}else Notify("MISSION FAILED / EXTRACTION PAYOUT ONLY","任務失敗 / 脱出報酬のみ");}else AwardCredits(ScaleScrap(Mathf.Min(1000000,kills*10000)));shopCycle++;shopPurchased.Clear();CreateShopStock();SaveProgression();}
  void GrantExpeditionReward(int stageId){if(clearedExpeditionStages.Contains(stageId))return;var r=new System.Random(ExpeditionMap.RewardSeed(stageId));int kind=r.Next(4);var stage=ExpeditionMap.Get(stageId);switch(kind){case 0:AwardCredits(ScaleScrap(250000+r.Next(250001)));break;case 1:var gear=Arsenal.RollForDungeon(r,stage.legacyDungeonIndex);if(!StoreWeapon(gear))AwardCredits(ScaleScrap(400000));break;case 2:AddAmmo((AmmoType)r.Next(4),20+r.Next(31));break;default:ExpeditionTokens++;break;}if(MissionCompleted)TryClaimMissionReward();clearedExpeditionStages.Add(stageId);SaveProgression();}
  public string ExpeditionRewardDescription(int stageId){var r=new System.Random(ExpeditionMap.RewardSeed(stageId));int kind=r.Next(4);if(kind==0){int amount=ScaleScrap(250000+r.Next(250001));return VaultLanguage.T("SCRAP +"+amount.ToString("N0"),"スクラップ +"+amount.ToString("N0"));}if(kind==1)return VaultLanguage.T("GEAR CACHE / weapon (salvage if full)", "装備箱 / 銃（満杯時は換金）");if(kind==2){int type=r.Next(4),amount=20+r.Next(31);string en=AmmoEnglish((AmmoType)type),ja=AmmoJapanese((AmmoType)type);return VaultLanguage.T(en+" +"+amount,ja+" +"+amount);}return VaultLanguage.T("SKILL TOKEN +1","スキルトークン +1");}
  public void AwardCredits(int amount){Credits=Mathf.Max(0,Credits+Mathf.Max(0,amount));SaveProgression();}
  public bool TrySpendCredits(int amount){if(amount<=0||Credits<amount)return false;Credits-=amount;SaveProgression();return true;}
  void CreateShopStock(){shopStock.Clear();var r=new System.Random(51031+shopCycle*7919+HighestUnlocked*173);for(int i=0;i<4;i++){var offer=new ShopOffer();int level=DungeonCatalog.ItemLevel(r,HighestUnlocked);Rarity rarity=i==3?Rarity.Rare:Rarity.Uncommon;if(i==0||i==1)offer.gun=Arsenal.CreateForDungeon(r,HighestUnlocked,rarity,level);else if(i==2)offer.armor=Armory.CreateForDungeon(r,HighestUnlocked,rarity,level);else offer.artifact=ArtifactCatalog.Create(r,HighestUnlocked,rarity,level);offer.cost=Mathf.Clamp((5000+level*300+(int)rarity*3500)*ScrapLevelMultiplier,5000,30000*ScrapLevelMultiplier);offer.purchased=shopPurchased.Contains(i);shopStock.Add(offer);}var melee=new ShopOffer{melee=MeleeWeaponCatalog.Create(r,DungeonCatalog.ItemLevel(r,HighestUnlocked))};melee.cost=(7500+melee.melee.level*800)*ScrapLevelMultiplier;melee.purchased=shopPurchased.Contains(4);shopStock.Add(melee);}
  public bool PurchaseShop(int index){if(index<0||index>=shopStock.Count)return false;var o=shopStock[index];int price=ShopOfferPrice(o);if(o.purchased||Credits<price)return false;bool stored=o.gun!=null?StoreWeapon(o.gun):o.armor!=null?StoreArmor(o.armor):o.artifact!=null?StoreArtifact(o.artifact):StoreMeleeWeapon(o.melee);if(!stored){Notify("Storage full. Discard unused equipment.","所持枠が満杯です。不要な装備を整理してください。");return false;}Credits-=price;o.purchased=true;shopPurchased.Add(index);SaveProgression();return true;}
  public bool StoreArtifact(ArtifactItem a){if(a==null||ArtifactInventory.Count>=ArtifactCapacity)return false;if(!ArtifactInventory.Contains(a))ArtifactInventory.Add(a);SaveProgression();return true;}
  public void EquipArtifact(ArtifactItem a,int slot){if(slot<0||slot>1||!ArtifactInventory.Contains(a))return;for(int i=0;i<2;i++)if(EquippedArtifacts[i]==a)EquippedArtifacts[i]=null;var displaced=EquippedArtifacts[slot];if(displaced!=null&&displaced!=a)reloadSurgeExpiry.Remove(displaced.id);EquippedArtifacts[slot]=a;RefreshReloadSurgeSummary();RecalculateArmor();SaveProgression();}
  public void UnequipArtifact(int slot){if(slot<0||slot>1)return;var removed=EquippedArtifacts[slot];if(removed!=null)reloadSurgeExpiry.Remove(removed.id);EquippedArtifacts[slot]=null;RefreshReloadSurgeSummary();RecalculateArmor();SaveProgression();}
  public void DiscardArtifact(ArtifactItem a){if(Array.IndexOf(EquippedArtifacts,a)>=0)return;if(a==null)return;ArtifactInventory.Remove(a);reloadSurgeExpiry.Remove(a.id);artifactTimers.Remove(a.id);RefreshReloadSurgeSummary();SaveProgression();}
  public void ResetArtifactCombat(){ArtifactShield=0;reloadSurge=0;artifactCombatClock=0;reloadSurgeExpiry.Clear();armorKillTimer=0;armorDashTimer=0;artifactTimers.Clear();}
  public void TickArtifacts(float dt){ArtifactShield=Mathf.Max(0,ArtifactShield-dt*2);artifactCombatClock+=Mathf.Max(0,dt);RefreshReloadSurgeSummary();armorKillTimer=Mathf.Max(0,armorKillTimer-dt);armorDashTimer=Mathf.Max(0,armorDashTimer-dt);foreach(var key in new List<string>(artifactTimers.Keys))artifactTimers[key]=Mathf.Max(0,artifactTimers[key]-dt);}
  public float ArtifactReloadSurgeRemaining(ArtifactItem a)=>a!=null&&a.effect==ArtifactEffect.ReloadSurge&&!string.IsNullOrEmpty(a.id)&&reloadSurgeExpiry.TryGetValue(a.id,out float expiry)?Mathf.Max(0,expiry-artifactCombatClock):0;
  void RefreshReloadSurgeSummary(){reloadSurge=0;foreach(var a in EquippedArtifacts)if(a!=null)reloadSurge=Mathf.Max(reloadSurge,ArtifactReloadSurgeRemaining(a));}
  public float ArtifactDamageMultiplier{get{float bonus=0;foreach(var a in EquippedArtifacts)if(a!=null){if(a.effect==ArtifactEffect.ReloadSurge&&ArtifactReloadSurgeRemaining(a)>0)bonus+=.15f*a.power;if(a.effect==ArtifactEffect.ShieldConversion&&ArtifactShield>0)bonus+=.12f*a.power;}foreach(var armor in EquippedArmor)if(armor!=null&&armor.uniqueEffect==3&&ArtifactShield>0){bonus+=.15f;break;}return 1+bonus;}}
  public float AbsorbArtifactDamage(float damage){float absorbed=Mathf.Min(ArtifactShield,damage);ArtifactShield-=absorbed;return damage-absorbed;}
  public void ArtifactOnKill(Vector3 position){if(armorKillTimer<=0){foreach(var armor in EquippedArmor)if(armor!=null&&armor.uniqueEffect==1){ArtifactShield=Mathf.Min(30,ArtifactShield+4);armorKillTimer=4;break;}}for(int i=0;i<2;i++){var a=EquippedArtifacts[i];if(a==null||ArtifactTimer(a)>0||a.effect!=ArtifactEffect.KillShield)continue;ArtifactShield=Mathf.Min(30,ArtifactShield+8*a.power);artifactTimers[a.id]=a.cooldown;}}
  public void ArtifactOnReload(){for(int i=0;i<2;i++){var a=EquippedArtifacts[i];if(a!=null&&ArtifactTimer(a)<=0&&a.effect==ArtifactEffect.ReloadSurge){reloadSurgeExpiry[a.id]=artifactCombatClock+3;artifactTimers[a.id]=a.cooldown;}}RefreshReloadSurgeSummary();}
  public void ArtifactOnDash(){if(armorDashTimer<=0){foreach(var armor in EquippedArmor)if(armor!=null&&armor.uniqueEffect==2){hp=Mathf.Min(maxHp,hp+4);armorDashTimer=5;break;}}for(int i=0;i<2;i++){var a=EquippedArtifacts[i];if(a==null||ArtifactTimer(a)>0||a.effect!=ArtifactEffect.DashPulse)continue;artifactTimers[a.id]=a.cooldown;foreach(var f in Enemies.ToArray())if(f!=null&&Vector3.Distance(f.transform.position,PlayerPosition)<3.5f)f.Hit(12*a.power);Burst(PlayerPosition,Cyan,12);}}
  class ArtifactDrop{public ArtifactItem item;public Vector3 position;public GameObject visual;}
  readonly List<ArtifactDrop> artifactDrops=new List<ArtifactDrop>();
  ArtifactDrop NearArtifact(){ArtifactDrop nearest=null;float distance=2.6f;foreach(var d in artifactDrops){float n=Vector3.Distance(PlayerPosition,d.position);if(n<distance){nearest=d;distance=n;}}return nearest;}
  public ArtifactItem NearbyArtifact=>NearArtifact()?.item;
  public void AddArtifactDrop(ArtifactItem item,Vector3 position){if(item==null)return;position.y=.5f;var visual=CreateLootPresentation(item.Name,position,new Vector3(.45f,.3f,.55f),Arsenal.Colors[(int)item.rarity],LootPresentationKind.Module);artifactDrops.Add(new ArtifactDrop{item=item,position=position,visual=visual});}
  public void ClearArtifactDrops(){foreach(var d in artifactDrops)if(d.visual!=null)Destroy(d.visual);artifactDrops.Clear();}
  public bool PickupArtifactNearest(){var d=NearArtifact();if(d==null)return false;float distance=Vector3.Distance(PlayerPosition,d.position);var weapon=NearDrop();var armor=NearArmor();if(weapon!=null&&Vector3.Distance(PlayerPosition,weapon.position)<distance)return false;if(armor!=null&&Vector3.Distance(PlayerPosition,armor.position)<distance)return false;if(!StoreArtifact(d.item)){Notify("Artifact storage full. Discard unused artifacts in [I].","拡張モジュール枠が満杯です。[I]で整理してください。");return true;}artifactDrops.Remove(d);Destroy(d.visual);Notify(ArtifactCatalog.DisplayName(d.item,false)+" collected. Equip in one of two slots [I].",ArtifactCatalog.DisplayName(d.item,true)+"を入手。2枠のいずれかに装備できます [I]");return true;}
